import { RegExpParser } from "regexpp"
import { UsageOfPattern } from "../utils/get-usage-of-pattern"
import { canReorder } from "../utils/reorder-alternatives"
import { mention, mentionChar } from "../utils/mention"

type ParentNode = Group | CapturingGroup | Pattern | LookaroundAssertion
type NestedElement = Alternative | CharacterClassElement

/** Yields removable branches and character class elements, outermost first. */
function* getNestedElements(
    node: Alternative | Element | CharacterClassElement,
): Iterable<NestedElement> {
    switch (node.type) {
        case "Alternative":
            for (const element of node.elements) {
                yield* getNestedElements(element)
            }
            break
        case "Group":
        case "CapturingGroup":
            for (const alternative of node.alternatives) {
                if (node.alternatives.length > 1) {
                    yield alternative
                }
                yield* getNestedElements(alternative)
            }
            break
        case "Quantifier":
            if (node.max > 0) {
                yield* getNestedElements(node.element)
            }
            break
        case "CharacterClass":
            if (!node.negate) {
                for (const element of node.elements) {
                    yield element
                    if (
                        element.type === "CharacterClassRange" &&
                        element.min.value < element.max.value
                    ) {
                        yield element.min
                        yield element.max
                    }
                }
            }
            break
        default:
            break
    }
}

/**
 * Builds the paths of an alternative that pass through a nested element.
 * A character outside the input alphabet marks visits to the nested element.
 * Keeping the original alternatives and quantifiers preserves all legal
 * iteration counts, including iterations that don't visit the element.
 */
function getNestedExpression(
    parser: JS.Parser,
    alternative: Alternative,
    nested: NestedElement,
): NoParent<Expression> {
    /** Parses an unchanged part of the surrounding alternative. */
    function parse(element: JS.ParsableElement): NoParent<REElement> {
        return {
            type: "Alternation",
            alternatives: parser.parseElement(element, {
                backreferences: "unknown",
                assertions: "parse",
                maxBackreferenceWords: 0,
            }).expression.alternatives,
        }
    }

    /** Wraps a sequence of elements in an alternation. */
    function concat(elements: NoParent<REElement>[]): NoParent<REElement> {
        return {
            type: "Alternation",
            alternatives: [{ type: "Concatenation", elements }],
        }
    }

    const markerCharacter = Number(parser.maxCharacter) + 1
    const marker: NoParent<REElement> = {
        type: "CharacterClass",
        characters: CharSet.fromCharacters(markerCharacter, [markerCharacter]),
    }
    let current: Node = nested
    let selected: NoParent<REElement>
    if (nested.type === "Alternative") {
        selected = concat([marker, parse(nested)])
    } else {
        current = nested.parent
        if (current.type === "CharacterClassRange") {
            current = current.parent
        }
        selected = {
            type: "Alternation",
            alternatives: [
                {
                    type: "Concatenation",
                    elements: [parse(current)],
                },
                {
                    type: "Concatenation",
                    elements: [
                        marker,
                        {
                            type: "CharacterClass",
                            characters: toCharSet(nested, parser.ast.flags),
                        },
                    ],
                },
            ],
        }
    }

    while (current !== alternative) {
        const parent: Node = current.parent
        switch (parent.type) {
            case "Alternative": {
                const elements: NoParent<REElement>[] = []
                for (const e of parent.elements) {
                    elements.push(e === current ? selected : parse(e))
                }
                selected = concat(elements)
                break
            }
            case "Group":
            case "CapturingGroup": {
                const alternatives: NoParent<Expression>["alternatives"] = []
                for (const a of parent.alternatives) {
                    alternatives.push({
                        type: "Concatenation",
                        elements: [a === current ? selected : parse(a)],
                    })
                }
                selected = { type: "Alternation", alternatives }
                break
            }
            case "Quantifier":
                selected = {
                    type: "Quantifier",
                    min: parent.min,
                    max: parent.max,
                    lazy: !parent.greedy,
                    alternatives: [
                        { type: "Concatenation", elements: [selected] },
                    ],
                }
                break
            default:
                throw new Error("Unexpected parent of a nested element.")
        }
        current = parent
    }

    return {
        type: "Expression",
        alternatives: [{ type: "Concatenation", elements: [selected] }],
    }
}

/**
 * Returns an NFA containing all paths that visit the nested element.
 * Assertions and unresolved backreferences are conservatively approximated.
 */
function toNestedNFA(
    parser: JS.Parser,
    alternative: Alternative,
    nested: NestedElement,
): NFA {
    const expression = getNestedExpression(parser, alternative, nested)
    const maxCharacter = parser.maxCharacter
    const marker = Number(maxCharacter) + 1

    visitAst(expression, {
        onConcatenationEnter(concat) {
            // Assertions consume nothing and unknown backreferences may consume
            // any word. Over-approximating them is safe for the subset being
            // tested, and prevents assertions from inspecting the marker.
            concat.elements = concat.elements
                .filter((e) => e.type !== "Assertion")
                .map((e) => {
                    if (e.type !== "Unknown") {
                        return e
                    }
                    return {
                        type: "Quantifier",
                        min: 0,
                        max: Infinity,
                        lazy: false,
                        alternatives: [
                            {
                                type: "Concatenation",
                                elements: [
                                    {
                                        type: "CharacterClass",
                                        characters: CharSet.all(maxCharacter),
                                    },
                                ],
                            },
                        ],
                    }
                })
        },
        onCharacterClassEnter(cc) {
            cc.characters = CharSet.empty(marker).union(cc.characters.ranges)
        },
    })

    const marked = NFA.fromRegex(expression, { maxCharacter: marker })
    const result = ENFA.empty({ maxCharacter })
    const states = new Map<
        NFA.Node,
        { before: ENFA.Node; after: ENFA.Node; mark: ENFA.Node }
    >()
    for (const state of marked.nodes) {
        const before = result.nodes.createNode()
        const after = result.nodes.createNode()
        const mark = result.nodes.createNode()
        result.nodes.linkNodes(mark, after, null)
        states.set(state, { before, after, mark })
        if (marked.nodes.finals.has(state)) {
            result.nodes.linkNodes(after, result.nodes.final, null)
        }
    }
    result.nodes.linkNodes(
        result.nodes.initial,
        states.get(marked.nodes.initial)!.before,
        null,
    )
    for (const [state, from] of states) {
        for (const [target, chars] of state.out) {
            const to = states.get(target)!
            if (chars.has(marker)) {
                result.nodes.linkNodes(from.before, to.mark, null)
                result.nodes.linkNodes(from.after, to.mark, null)
            }
            const actualChars = CharSet.empty(maxCharacter).union(
                chars.without([{ min: marker, max: marker }]).ranges,
            )
            if (!actualChars.isEmpty) {
                result.nodes.linkNodes(from.before, to.before, actualChars)
                result.nodes.linkNodes(from.after, to.after, actualChars)
            }
        }
    }
    return NFA.fromFA(result)
}

/**
 * Returns whether the node or the elements of the node are effectively
 * quantified with a star.
 */
function isStared(node: Node): boolean {
    let max = getEffectiveMaximumRepetition(node)
    if (node.type === "Quantifier") {
        max *= node.max
    }
    return max > 10
}

/**
 * Check has after pattern
 */
function hasNothingAfterNode(node: ParentNode): boolean {
    const md = getMatchingDirection(node)

    for (
        let p:
            | Group
            | Pattern
            | CapturingGroup
            | LookaroundAssertion
            | Quantifier
            | Alternative = node;
        ;
        p = p.parent
    ) {
        if (p.type === "Assertion" || p.type === "Pattern") {
            return true
        }

        if (p.type !== "Alternative") {
            const parent: Quantifier | Alternative = p.parent
            if (parent.type === "Quantifier") {
                if (parent.max > 1) {
                    return false
                }
            } else {
                const lastIndex: number =
                    md === "ltr" ? parent.elements.length - 1 : 0
                if (parent.elements[lastIndex] !== p) {
                    return false
                }
            }
        }
    }
}

/**
 * Returns whether the given RE AST contains assertions.
 */
function containsAssertions(expression: NoParent<Expression>): boolean {
    try {
        visitAst(expression, {
            onAssertionEnter() {
                throw new Error()
            },
        })
        return false
    } catch (error) {
        return true
    }
}

/**
 * Returns whether the given RE AST contains assertions or unknowns.
 */
function containsAssertionsOrUnknowns(
    expression: NoParent<Expression>,
): boolean {
    try {
        visitAst(expression, {
            onAssertionEnter() {
                throw new Error()
            },
            onUnknownEnter() {
                throw new Error()
            },
        })
        return false
    } catch (error) {
        return true
    }
}

const creationOption: Transformers.CreationOptions = {
    ignoreAmbiguity: true,
    ignoreOrder: true,
}
const assertionTransformer = combineTransformers([
    Transformers.applyAssertions(creationOption),
    Transformers.removeUnnecessaryAssertions(creationOption),
    Transformers.inline(creationOption),
    Transformers.removeDeadBranches(creationOption),
])

/**
 * Create an NFA from the given element.
 *
 * The `partial` value determines whether the NFA perfectly represents the given
 * element. Some elements might contain features that cannot be represented
 * using NFA in which case a partial NFA will be created (e.g. the NFA of
 * `a|\bfoo\b` is equivalent to the NFA of `a`).
 */
function toNFA(
    parser: JS.Parser,
    element: JS.ParsableElement,
): { nfa: NFA; partial: boolean } {
    try {
        const { expression, maxCharacter } = parser.parseElement(element, {
            backreferences: "unknown",
            assertions: "parse",
        })

        let e
        if (containsAssertions(expression)) {
            e = transform(assertionTransformer, expression)
        } else {
            e = expression
        }

        return {
            nfa: NFA.fromRegex(
                e,
                { maxCharacter },
                { assertions: "disable", unknowns: "disable" },
            ),
            partial: containsAssertionsOrUnknowns(e),
        }
    } catch (error) {
        return {
            nfa: NFA.empty({
                maxCharacter: parser.ast.flags.unicode ? 0x10ffff : 0xffff,
            }),
            partial: true,
        }
    }
}

/**
 * Unions all given NFAs
 */
function unionAll(nfas: readonly ReadonlyNFA[]): ReadonlyNFA {
    if (nfas.length === 0) {
        throw new Error("Cannot union 0 NFAs.")
    } else if (nfas.length === 1) {
        return nfas[0]
    }

    const total = nfas[0].copy()
    for (let i = 1; i < nfas.length; i++) {
        total.union(nfas[i])
    }
    return total
}

const DFA_OPTIONS: DFA.CreationOptions = { maxNodes: 100_000 }

/**
 * Returns whether one NFA is a subset of another.
 */
function isSubsetOf(
    superset: ReadonlyNFA,
    subset: ReadonlyNFA,
): boolean | null {
    try {
        const a = DFA.fromIntersection(superset, subset, DFA_OPTIONS)
        const b = DFA.fromFA(subset, DFA_OPTIONS)
        a.minimize()
        b.minimize()
        return a.structurallyEqual(b)
    } catch (error) {
        return null
    }
}

const enum SubsetRelation {
    none,
    leftEqualRight,
    leftSubsetOfRight,
    leftSupersetOfRight,
    unknown,
}

/**
 * Returns the subset relation
 */
function getSubsetRelation(
    left: ReadonlyNFA,
    right: ReadonlyNFA,
): SubsetRelation {
    try {
        const inter = DFA.fromIntersection(left, right, DFA_OPTIONS)
        inter.minimize()

        const l = DFA.fromFA(left, DFA_OPTIONS)
        l.minimize()

        const r = DFA.fromFA(right, DFA_OPTIONS)
        r.minimize()

        const subset = l.structurallyEqual(inter)
        const superset = r.structurallyEqual(inter)

        if (subset && superset) {
            return SubsetRelation.leftEqualRight
        } else if (subset) {
            return SubsetRelation.leftSubsetOfRight
        } else if (superset) {
            return SubsetRelation.leftSupersetOfRight
        }
        return SubsetRelation.none
    } catch (error) {
        return SubsetRelation.unknown
    }
}

/**
 * The `getSubsetRelation` function assumes that both NFAs perfectly represent
 * their language.
 *
 * This function adjusts their subset relation to account for partial NFAs.
 */
function getPartialSubsetRelation(
    left: ReadonlyNFA,
    leftIsPartial: boolean,
    right: ReadonlyNFA,
    rightIsPartial: boolean,
): SubsetRelation {
    const relation = getSubsetRelation(left, right)

    if (!leftIsPartial && !rightIsPartial) {
        return relation
    }

    if (
        relation === SubsetRelation.none ||
        relation === SubsetRelation.unknown
    ) {
        return relation
    }

    if (leftIsPartial && !rightIsPartial) {
        switch (relation) {
            case SubsetRelation.leftEqualRight:
                return SubsetRelation.leftSupersetOfRight
            case SubsetRelation.leftSubsetOfRight:
                return SubsetRelation.none
            case SubsetRelation.leftSupersetOfRight:
                return SubsetRelation.leftSupersetOfRight

            default:
                throw new Error(relation)
        }
    }
    if (rightIsPartial && !leftIsPartial) {
        switch (relation) {
            case SubsetRelation.leftEqualRight:
                return SubsetRelation.leftSubsetOfRight
            case SubsetRelation.leftSubsetOfRight:
                return SubsetRelation.leftSubsetOfRight
            case SubsetRelation.leftSupersetOfRight:
                return SubsetRelation.none

            default:
                throw new Error(relation)
        }
    }

    // both are partial

    return SubsetRelation.none
}

/**
 * Returns the regex source of the given FA.
 */
function faToSource(fa: FiniteAutomaton, flags: ReadonlyFlags): string {
    try {
        return JS.toLiteral(fa.toRegex(), { flags }).source
    } catch (error) {
        return "<ERROR>"
    }
}

interface ResultBase {
    alternative: Alternative
    others: Alternative[]
}
interface DuplicateResult extends ResultBase {
    type: "Duplicate"
    others: [Alternative]
}
interface SubsetResult extends ResultBase {
    type: "Subset"
}
interface PrefixSubsetResult extends ResultBase {
    type: "PrefixSubset"
}
interface NestedSubsetResult extends ResultBase {
    type: "NestedSubset" | "NestedPrefixSubset"
    nested: NestedElement
}
interface SupersetResult extends ResultBase {
    type: "Superset"
}
interface OverlapResult extends ResultBase {
    type: "Overlap"
    overlap: NFA
}
type Result =
    | DuplicateResult
    | SubsetResult
    | PrefixSubsetResult
    | NestedSubsetResult
    | SupersetResult
    | OverlapResult

interface Options {
    parser: JS.Parser
    hasNothingAfter: boolean
    fastAst: boolean
    noNfa: boolean
    ignoreOverlap: boolean
}

/**
 * Tries to find duplication in the given alternatives
 */
function* findDuplicationAstFast(
    alternatives: Alternative[],
    flags: ReadonlyFlags,
): Iterable<Result> {
    // eslint-disable-next-line func-style -- x
    const shortCircuit: Parameters<typeof isEqualNodes>[3] = (a) => {
        return a.type === "CapturingGroup" ? false : null
    }

    for (let i = 0; i < alternatives.length; i++) {
        const alternative = alternatives[i]

        for (let j = 0; j < i; j++) {
            const other = alternatives[j]

            if (isEqualNodes(other, alternative, flags, shortCircuit)) {
                yield { type: "Duplicate", alternative, others: [other] }
            }
        }
    }
}

/**
 * Tries to find duplication in the given alternatives
 */
function* findDuplicationAst(
    alternatives: Alternative[],
    flags: ReadonlyFlags,
    hasNothingAfter: boolean,
): Iterable<Result> {
    // The AST comparison only supports omitting a suffix. In lookbehind,
    // leave prefix coverage to the direction-aware NFA comparison.
    const canOmitRight =
        hasNothingAfter &&
        alternatives.every((a) => getMatchingDirection(a) === "ltr")
    const isCoveredOptions: Parameters<typeof isCoveredNode>[2] = {
        flags,
        canOmitRight,
    }
    const isCoveredOptionsNoPrefix: Parameters<typeof isCoveredNode>[2] = {
        flags,
        canOmitRight: false,
    }

    for (let i = 0; i < alternatives.length; i++) {
        const alternative = alternatives[i]

        for (let j = 0; j < i; j++) {
            const other = alternatives[j]

            if (isCoveredNode(other, alternative, isCoveredOptions)) {
                if (isEqualNodes(other, alternative, flags)) {
                    yield {
                        type: "Duplicate",
                        alternative,
                        others: [other],
                    }
                } else if (
                    canOmitRight &&
                    !isCoveredNode(other, alternative, isCoveredOptionsNoPrefix)
                ) {
                    yield {
                        type: "PrefixSubset",
                        alternative,
                        others: [other],
                    }
                } else {
                    yield { type: "Subset", alternative, others: [other] }
                }
            }
        }
    }
}

/** Finds nested paths covered by earlier alternatives. */
function* findNestedDuplication(
    alternative: Alternative,
    previous: [NFA, boolean, Alternative][],
    parser: JS.Parser,
    prefix: boolean,
): Iterable<NestedSubsetResult> {
    if (previous.length === 0) {
        return
    }

    const covered: NestedElement[] = []
    for (const nested of getNestedElements(alternative)) {
        if (
            covered.some((n) => n.start <= nested.start && nested.end <= n.end)
        ) {
            continue
        }

        let nfa: NFA
        try {
            nfa = toNestedNFA(parser, alternative, nested)
        } catch (error) {
            continue
        }
        if (nfa.isEmpty) {
            continue
        }

        const overlapping = previous.filter(
            ([other]) => !nfa.isDisjointWith(other),
        )
        if (
            overlapping.length > 0 &&
            isSubsetOf(unionAll(overlapping.map(([other]) => other)), nfa)
        ) {
            covered.push(nested)
            yield {
                type: prefix ? "NestedPrefixSubset" : "NestedSubset",
                alternative,
                nested,
                others: overlapping.map(([, , other]) => other),
            }
        }
    }
}

/**
 * Tries to find duplication in the given alternatives.
 *
 * It will search for prefix duplications. I.e. the alternative `ab` in `a|ab`
 * is a duplicate of `a` because if `ab` accepts, `a` will have already accepted
 * the input string. This makes `ab` effectively useless.
 *
 * This operation will modify the given NFAs.
 */
function* findPrefixDuplicationNfa(
    alternatives: [NFA, boolean, Alternative][],
    parser: JS.Parser,
    skipNested: ReadonlySet<Alternative>,
): Iterable<Result> {
    if (alternatives.length === 0) {
        return
    }

    // For two alternatives `A|B`, `B` is useless if `B` is a subset of `A[^]*`

    const all = NFA.all({ maxCharacter: alternatives[0][0].maxCharacter })

    for (let i = 0; i < alternatives.length; i++) {
        const [nfa, partial, alternative] = alternatives[i]

        if (!partial) {
            const overlapping = alternatives
                .slice(0, i)
                .filter(([otherNfa]) => !nfa.isDisjointWith(otherNfa))

            if (overlapping.length >= 1) {
                const othersNfa = unionAll(overlapping.map(([n]) => n))
                const others = overlapping.map(([, , a]) => a)

                // Only checking for a subset relation is sufficient here.
                // Duplicates are VERY unlikely. (Who would use alternatives
                // like `a|a[^]*`?)

                if (isSubsetOf(othersNfa, nfa)) {
                    yield { type: "PrefixSubset", alternative, others }
                }
            }
        }

        if (!skipNested.has(alternative)) {
            yield* findNestedDuplication(
                alternative,
                alternatives.slice(0, i),
                parser,
                true,
            )
        }

        if (getMatchingDirection(alternative) === "ltr") {
            nfa.append(all)
        } else {
            nfa.prepend(all)
        }
    }
}

/**
 * Tries to find duplication in the given alternatives.
 */
function* findDuplicationNfa(
    alternatives: Alternative[],
    flags: ReadonlyFlags,
    { hasNothingAfter, parser, ignoreOverlap }: Options,
): Iterable<Result> {
    const previous: [NFA, boolean, Alternative][] = []
    const skipNested = new Set<Alternative>()
    for (let i = 0; i < alternatives.length; i++) {
        const alternative = alternatives[i]
        const { nfa, partial } = toNFA(parser, alternative)

        const overlapping = previous.filter(
            ([otherNfa]) => !nfa.isDisjointWith(otherNfa),
        )

        if (overlapping.length >= 1) {
            const othersNfa = unionAll(overlapping.map(([n]) => n))
            const othersPartial = overlapping.some(([, p]) => p)
            const others = overlapping.map(([, , a]) => a)

            const relation = getPartialSubsetRelation(
                nfa,
                partial,
                othersNfa,
                othersPartial,
            )

            switch (relation) {
                case SubsetRelation.leftEqualRight:
                    skipNested.add(alternative)
                    if (others.length === 1) {
                        // only return "duplicate" if there is only one other
                        // alternative
                        yield {
                            type: "Duplicate",
                            alternative,
                            others: [others[0]],
                        }
                    } else {
                        yield { type: "Subset", alternative, others }
                    }
                    break

                case SubsetRelation.leftSubsetOfRight:
                    skipNested.add(alternative)
                    yield { type: "Subset", alternative, others }
                    break

                case SubsetRelation.leftSupersetOfRight: {
                    const reorder = canReorder([alternative, ...others], flags)

                    if (reorder) {
                        // This alternative covers earlier removable ones. It
                        // must not in turn use them to justify removing its
                        // own nested elements.
                        skipNested.add(alternative)
                        // We are allowed to freely reorder the alternatives.
                        // This means that we can reverse the order of our
                        // alternatives to convert the superset into a subset.
                        for (const other of others) {
                            yield {
                                type: "Subset",
                                alternative: other,
                                others: [alternative],
                            }
                        }
                    } else {
                        yield { type: "Superset", alternative, others }
                    }
                    break
                }

                case SubsetRelation.none:
                case SubsetRelation.unknown:
                    if (!ignoreOverlap) {
                        yield {
                            type: "Overlap",
                            alternative,
                            others,
                            overlap: NFA.fromIntersection(nfa, othersNfa),
                        }
                    }
                    break

                default:
                    throw new Error(relation)
            }
        }

        if (!skipNested.has(alternative)) {
            yield* findNestedDuplication(alternative, previous, parser, false)
        }
        previous.push([nfa, partial, alternative])
    }

    if (hasNothingAfter) {
        yield* findPrefixDuplicationNfa(previous, parser, skipNested)
    }
}

/**
 * Tries to find duplication in the given alternatives
 */
function* findDuplication(
    alternatives: Alternative[],
    flags: ReadonlyFlags,
    options: Options,
): Iterable<Result> {
    // AST-based approach
    if (options.fastAst) {
        yield* findDuplicationAstFast(alternatives, flags)
    } else {
        yield* findDuplicationAst(alternatives, flags, options.hasNothingAfter)
    }

    // NFA-based approach
    if (!options.noNfa) {
        yield* findDuplicationNfa(alternatives, flags, options)
    }
}

const RESULT_TYPE_ORDER: Result["type"][] = [
    "Duplicate",
    "Subset",
    "PrefixSubset",
    "NestedSubset",
    "NestedPrefixSubset",
    "Superset",
    "Overlap",
]

/**
 * Returns an array of the given results that is sorted by result type from
 * most important to least important.
 */
function deduplicateResults(
    unsorted: Iterable<Result>,
    { reportExp }: FilterInfo,
): Result[] {
    const results = [...unsorted].sort(
        (a, b) =>
            RESULT_TYPE_ORDER.indexOf(a.type) -
            RESULT_TYPE_ORDER.indexOf(b.type),
    )

    const seen = new Map<Alternative, Result["type"]>()
    const nestedSeen = new Map<Alternative, NestedElement[]>()
    return results.filter((result) => {
        const { alternative, type } = result
        const firstSeen = seen.get(alternative)

        if (
            (type === "NestedSubset" || type === "NestedPrefixSubset") &&
            (firstSeen === undefined ||
                firstSeen === "NestedSubset" ||
                firstSeen === "NestedPrefixSubset")
        ) {
            const elements = nestedSeen.get(alternative) || []
            if (
                elements.some(
                    (n) =>
                        n.start <= result.nested.start &&
                        result.nested.end <= n.end,
                )
            ) {
                return false
            }
            elements.push(result.nested)
            nestedSeen.set(alternative, elements)
            seen.set(alternative, firstSeen || type)
            return true
        }

        if (firstSeen === undefined) {
            seen.set(alternative, type)
            return true
        }

        if (
            reportExp &&
            (firstSeen === "PrefixSubset" ||
                firstSeen === "NestedPrefixSubset") &&
            (type === "Superset" || type === "Overlap")
        ) {
            // Prefix subset might overshadow some other results (Superset or
            // Overlap) that report exponential backtracking. In this case, we
            // want to report BOTH the Prefix subset and one Superset or
            // Overlap.
            seen.set(alternative, type)
            return true
        }

        return false
    })
}

/**
 * Throws if called.
 */
function assertNever(value: never): never {
    throw new Error(`Invalid value: ${value}`)
}

const enum ReportOption {
    all = "all",
    trivial = "trivial",
    interesting = "interesting",
}
const enum ReportExponentialBacktracking {
    none = "none",
    certain = "certain",
    potential = "potential",
}
const enum ReportUnreachable {
    certain = "certain",
    potential = "potential",
}

const enum MaybeBool {
    false = 0,
    true = 1,
    maybe = 2,
}

interface FilterInfo {
    stared: MaybeBool
    nothingAfter: MaybeBool

    reportExp: boolean
    reportPrefix: boolean
}

export default createRule("no-dupe-disjunctions", {
    meta: {
        docs: {
            description: "disallow duplicate disjunctions",
            category: "Possible Errors",
            recommended: true,
        },
        schema: [
            {
                type: "object",
                properties: {
                    report: {
                        type: "string",
                        enum: ["all", "trivial", "interesting"],
                    },
                    reportExponentialBacktracking: {
                        enum: ["none", "certain", "potential"],
                    },
                    reportUnreachable: {
                        enum: ["certain", "potential"],
                    },
                },
                additionalProperties: false,
            },
        ],
        messages: {
            duplicate:
                "Unexpected duplicate alternative. This alternative can be removed.{{cap}}{{exp}}",
            subset: "Unexpected useless alternative. This alternative is a strict subset of {{others}} and can be removed.{{cap}}{{exp}}",
            prefixSubset:
                "Unexpected useless alternative. This alternative is already covered by {{others}} and can be removed.{{cap}}",
            nestedSubset:
                "Unexpected useless element. All paths of {{alternative}} that go through {{nested}} are a strict subset of {{others}}. This element can be removed.{{cap}}",
            nestedPrefixSubset:
                "Unexpected useless element. All paths of {{alternative}} that go through {{nested}} are already covered by {{others}}. This element can be removed.{{cap}}",
            superset:
                "Unexpected superset. This alternative is a superset of {{others}}. It might be possible to remove the other alternative(s).{{cap}}{{exp}}",
            overlap:
                "Unexpected overlap. This alternative overlaps with {{others}}. The overlap is {{expr}}.{{cap}}{{exp}}",
        },
        type: "suggestion", // "problem",
    },
    create(context) {
        const reportExponentialBacktracking: ReportExponentialBacktracking =
            context.options[0]?.reportExponentialBacktracking ??
            ReportExponentialBacktracking.potential
        const reportUnreachable: ReportUnreachable =
            context.options[0]?.reportUnreachable ?? ReportUnreachable.certain
        const report: ReportOption =
            context.options[0]?.report ?? ReportOption.trivial

        /**
         * Create visitor
         */
        function createVisitor(
            regexpContext: RegExpContext,
        ): RegExpVisitor.Handlers {
            const {
                patternAst,
                flagsString,
                flags,
                node,
                getRegexpLocation,
                getUsageOfPattern,
            } = regexpContext

            const parser = JS.Parser.fromAst({
                pattern: patternAst,
                flags: new RegExpParser().parseFlags(
                    [
                        ...new Set(
                            (flagsString || "").replace(/[^gimsuy]/gu, ""),
                        ),
                    ].join(""),
                ),
            })
            const reportedNested: NestedElement[] = []

            /** Returns the filter information for the given node */
            function getFilterInfo(parentNode: ParentNode): FilterInfo {
                const usage = getUsageOfPattern()

                let stared: MaybeBool
                if (isStared(parentNode)) {
                    stared = MaybeBool.true
                } else if (
                    usage === UsageOfPattern.partial ||
                    usage === UsageOfPattern.mixed
                ) {
                    stared = MaybeBool.maybe
                } else {
                    stared = MaybeBool.false
                }

                // eslint-disable-next-line one-var -- false positive
                let nothingAfter: MaybeBool
                if (!hasNothingAfterNode(parentNode)) {
                    nothingAfter = MaybeBool.false
                } else if (
                    usage === UsageOfPattern.partial ||
                    usage === UsageOfPattern.mixed
                ) {
                    nothingAfter = MaybeBool.maybe
                } else {
                    nothingAfter = MaybeBool.true
                }

                // eslint-disable-next-line one-var -- false positive
                let reportExp: boolean
                switch (reportExponentialBacktracking) {
                    case ReportExponentialBacktracking.none:
                        reportExp = false
                        break

                    case ReportExponentialBacktracking.certain:
                        reportExp = stared === MaybeBool.true
                        break

                    case ReportExponentialBacktracking.potential:
                        reportExp = stared !== MaybeBool.false
                        break

                    default:
                        assertNever(reportExponentialBacktracking)
                }

                // eslint-disable-next-line one-var -- false positive
                let reportPrefix: boolean
                switch (reportUnreachable) {
                    case ReportUnreachable.certain:
                        reportPrefix = nothingAfter === MaybeBool.true
                        break

                    case ReportUnreachable.potential:
                        reportPrefix = nothingAfter !== MaybeBool.false
                        break

                    default:
                        assertNever(reportUnreachable)
                }

                return { stared, nothingAfter, reportExp, reportPrefix }
            }

            /** Verify group node */
            function verify(parentNode: ParentNode) {
                const info = getFilterInfo(parentNode)

                const rawResults = findDuplication(
                    parentNode.alternatives,
                    flags,
                    {
                        fastAst: false,
                        noNfa: false,
                        ignoreOverlap:
                            !info.reportExp && report !== ReportOption.all,
                        hasNothingAfter: info.reportPrefix,
                        parser,
                    },
                )

                let results = filterResults([...rawResults], info)
                results = deduplicateResults(results, info)
                results.forEach((result) => reportResult(result, info))
            }

            /** Filters the results of a parent node. */
            function filterResults(
                results: Result[],
                { nothingAfter, reportExp, reportPrefix }: FilterInfo,
            ): Result[] {
                switch (report) {
                    case ReportOption.all: {
                        // We really want to report _everything_.
                        return results
                    }
                    case ReportOption.trivial: {
                        // For "trivial", we want to filter out all results
                        // where the user cannot just remove the reported
                        // alternative. So "Overlap" and "Superset" types are
                        // removed.

                        return results.filter(({ type }) => {
                            switch (type) {
                                case "Duplicate":
                                case "Subset":
                                case "NestedSubset":
                                    return true

                                case "Overlap":
                                case "Superset":
                                    return reportExp

                                case "PrefixSubset":
                                case "NestedPrefixSubset":
                                    return reportPrefix

                                default:
                                    throw assertNever(type)
                            }
                        })
                    }
                    case ReportOption.interesting: {
                        // For "interesting", we want to behave like "trivial"
                        // but we also want to retain "Superset" results like
                        // `\b(?:Foo|\w+)\b`. So "Overlap" types are always
                        // removed and "Superset" types are removed if there is
                        // nothing after it.

                        return results.filter(({ type }) => {
                            switch (type) {
                                case "Duplicate":
                                case "Subset":
                                case "NestedSubset":
                                    return true

                                case "Overlap":
                                    return reportExp

                                case "Superset":
                                    return (
                                        reportExp ||
                                        nothingAfter === MaybeBool.false
                                    )

                                case "PrefixSubset":
                                case "NestedPrefixSubset":
                                    return reportPrefix

                                default:
                                    throw assertNever(type)
                            }
                        })
                    }
                    default:
                        throw assertNever(report)
                }
            }

            /** Report the given result. */
            function reportResult(result: Result, { stared }: FilterInfo) {
                const reportNode =
                    "nested" in result ? result.nested : result.alternative
                if (
                    reportedNested.some(
                        (n) =>
                            n.start <= reportNode.start &&
                            reportNode.end <= n.end,
                    )
                ) {
                    return
                }
                let exp
                if (stared === MaybeBool.true) {
                    exp =
                        " This ambiguity is likely to cause exponential backtracking."
                } else if (stared === MaybeBool.maybe) {
                    exp =
                        " This ambiguity might cause exponential backtracking."
                } else {
                    exp = ""
                }

                const cap = hasSomeDescendant(
                    reportNode,
                    (d) => d.type === "CapturingGroup",
                )
                    ? " Careful! This alternative contains capturing groups which might be difficult to remove."
                    : ""

                const others = mention(
                    result.others.map((a) => a.raw).join("|"),
                )

                switch (result.type) {
                    case "NestedSubset":
                    case "NestedPrefixSubset":
                        reportedNested.push(result.nested)
                        context.report({
                            node,
                            loc: getRegexpLocation(result.nested),
                            messageId:
                                result.type === "NestedSubset"
                                    ? "nestedSubset"
                                    : "nestedPrefixSubset",
                            data: {
                                cap,
                                others,
                                alternative: mention(result.alternative),
                                nested:
                                    result.nested.type === "Alternative"
                                        ? mention(result.nested)
                                        : mentionChar(result.nested),
                            },
                        })
                        break

                    case "Duplicate":
                        context.report({
                            node,
                            loc: getRegexpLocation(result.alternative),
                            messageId: "duplicate",
                            data: { exp, cap, others },
                        })
                        break

                    case "Subset":
                        context.report({
                            node,
                            loc: getRegexpLocation(result.alternative),
                            messageId: "subset",
                            data: { exp, cap, others },
                        })
                        break

                    case "PrefixSubset":
                        context.report({
                            node,
                            loc: getRegexpLocation(result.alternative),
                            messageId: "prefixSubset",
                            data: { exp, cap, others },
                        })
                        break

                    case "Superset":
                        context.report({
                            node,
                            loc: getRegexpLocation(result.alternative),
                            messageId: "superset",
                            data: { exp, cap, others },
                        })
                        break

                    case "Overlap":
                        context.report({
                            node,
                            loc: getRegexpLocation(result.alternative),
                            messageId: "overlap",
                            data: {
                                exp,
                                cap,
                                others,
                                expr: mention(
                                    faToSource(result.overlap, flags),
                                ),
                            },
                        })
                        break

                    default:
                        throw new Error(result)
                }
            }

            return {
                onPatternEnter: verify,
                onGroupEnter: verify,
                onCapturingGroupEnter: verify,
                onAssertionEnter(aNode) {
                    if (
                        aNode.kind === "lookahead" ||
                        aNode.kind === "lookbehind"
                    ) {
                        verify(aNode)
                    }
                },
            }
        }

        return defineRegexpVisitor(context, {
            createVisitor,
        })
    },
})

import type { RegExpVisitor } from "regexpp/visitor"
import type {
    Alternative,
    CapturingGroup,
    CharacterClassElement,
    Element,
    Group,
    LookaroundAssertion,
    Node,
    Pattern,
    Quantifier,
} from "regexpp/ast"
import type { RegExpContext } from "../utils"
import { createRule, defineRegexpVisitor } from "../utils"
import { isCoveredNode, isEqualNodes } from "../utils/regexp-ast"
import type {
    Element as REElement,
    Expression,
    FiniteAutomaton,
    NoParent,
    ReadonlyNFA,
} from "refa"
import {
    combineTransformers,
    Transformers,
    DFA,
    ENFA,
    NFA,
    CharSet,
    JS,
    visitAst,
    transform,
} from "refa"
import type { ReadonlyFlags } from "regexp-ast-analysis"
import {
    hasSomeDescendant,
    getMatchingDirection,
    getEffectiveMaximumRepetition,
    toCharSet,
} from "regexp-ast-analysis"
import { RegExpParser } from "regexpp"
import { UsageOfPattern } from "../utils/get-usage-of-pattern"
import { canReorder } from "../utils/reorder-alternatives"
import { mention, mentionChar } from "../utils/mention"

type ParentNode = Group | CapturingGroup | Pattern | LookaroundAssertion
type NestedElement = Alternative | CharacterClassElement

/** Yields removable branches and character class elements, outermost first. */
function* getNestedElements(
    node: Alternative | Element | CharacterClassElement,
): Iterable<NestedElement> {
    switch (node.type) {
        case "Alternative":
            for (const element of node.elements) {
                yield* getNestedElements(element)
            }
            break
        case "Group":
        case "CapturingGroup":
            for (const alternative of node.alternatives) {
                if (node.alternatives.length > 1) {
                    yield alternative
                }
                yield* getNestedElements(alternative)
            }
            break
        case "Quantifier":
            if (node.max > 0) {
                yield* getNestedElements(node.element)
            }
            break
        case "CharacterClass":
            if (!node.negate) {
                for (const element of node.elements) {
                    yield element
                    if (
                        element.type === "CharacterClassRange" &&
                        element.min.value < element.max.value
                    ) {
                        yield element.min
                        yield element.max
                    }
                }
            }
            break
        default:
            break
    }
}

/**
 * Builds the paths of an alternative that pass through a nested element.
 * A character outside the input alphabet marks visits to the nested element.
 * Keeping the original alternatives and quantifiers preserves all legal
 * iteration counts, including iterations that don't visit the element.
 */
function getNestedExpression(
    parser: JS.Parser,
    alternative: Alternative,
    nested: NestedElement,
): NoParent<Expression> {
    /** Parses an unchanged part of the surrounding alternative. */
    function parse(element: JS.ParsableElement): NoParent<REElement> {
        return {
            type: "Alternation",
            alternatives: parser.parseElement(element, {
                backreferences: "unknown",
                assertions: "parse",
                maxBackreferenceWords: 0,
            }).expression.alternatives,
        }
    }

    /** Wraps a sequence of elements in an alternation. */
    function concat(elements: NoParent<REElement>[]): NoParent<REElement> {
        return {
            type: "Alternation",
            alternatives: [{ type: "Concatenation", elements }],
        }
    }

    const markerCharacter = Number(parser.maxCharacter) + 1
    const marker: NoParent<REElement> = {
        type: "CharacterClass",
        characters: CharSet.fromCharacters(markerCharacter, [markerCharacter]),
    }
    let current: Node = nested
    let selected: NoParent<REElement>
    if (nested.type === "Alternative") {
        selected = concat([marker, parse(nested)])
    } else {
        current = nested.parent
        if (current.type === "CharacterClassRange") {
            current = current.parent
        }
        selected = {
            type: "Alternation",
            alternatives: [
                {
                    type: "Concatenation",
                    elements: [parse(current)],
                },
                {
                    type: "Concatenation",
                    elements: [
                        marker,
                        {
                            type: "CharacterClass",
                            characters: toCharSet(nested, parser.ast.flags),
                        },
                    ],
                },
            ],
        }
    }

    while (current !== alternative) {
        const parent: Node = current.parent
        switch (parent.type) {
            case "Alternative": {
                const elements: NoParent<REElement>[] = []
                for (const e of parent.elements) {
                    elements.push(e === current ? selected : parse(e))
                }
                selected = concat(elements)
                break
            }
            case "Group":
            case "CapturingGroup": {
                const alternatives: NoParent<Expression>["alternatives"] = []
                for (const a of parent.alternatives) {
                    alternatives.push({
                        type: "Concatenation",
                        elements: [a === current ? selected : parse(a)],
                    })
                }
                selected = { type: "Alternation", alternatives }
                break
            }
            case "Quantifier":
                selected = {
                    type: "Quantifier",
                    min: parent.min,
                    max: parent.max,
                    lazy: !parent.greedy,
                    alternatives: [
                        { type: "Concatenation", elements: [selected] },
                    ],
                }
                break
            default:
                throw new Error("Unexpected parent of a nested element.")
        }
        current = parent
    }

    return {
        type: "Expression",
        alternatives: [{ type: "Concatenation", elements: [selected] }],
    }
}

/**
 * Returns an NFA containing all paths that visit the nested element.
 * Assertions and unresolved backreferences are conservatively approximated.
 */
function toNestedNFA(
    parser: JS.Parser,
    alternative: Alternative,
    nested: NestedElement,
): NFA {
    const expression = getNestedExpression(parser, alternative, nested)
    const maxCharacter = parser.maxCharacter
    const marker = Number(maxCharacter) + 1

    visitAst(expression, {
        onConcatenationEnter(concat) {
            // Assertions consume nothing and unknown backreferences may consume
            // any word. Over-approximating them is safe for the subset being
            // tested, and prevents assertions from inspecting the marker.
            concat.elements = concat.elements
                .filter((e) => e.type !== "Assertion")
                .map((e) => {
                    if (e.type !== "Unknown") {
                        return e
                    }
                    return {
                        type: "Quantifier",
                        min: 0,
                        max: Infinity,
                        lazy: false,
                        alternatives: [
                            {
                                type: "Concatenation",
                                elements: [
                                    {
                                        type: "CharacterClass",
                                        characters: CharSet.all(maxCharacter),
                                    },
                                ],
                            },
                        ],
                    }
                })
        },
        onCharacterClassEnter(cc) {
            cc.characters = CharSet.empty(marker).union(cc.characters.ranges)
        },
    })

    const marked = NFA.fromRegex(expression, { maxCharacter: marker })
    const result = ENFA.empty({ maxCharacter })
    const states = new Map<
        NFA.Node,
        { before: ENFA.Node; after: ENFA.Node; mark: ENFA.Node }
    >()
    for (const state of marked.nodes) {
        const before = result.nodes.createNode()
        const after = result.nodes.createNode()
        const mark = result.nodes.createNode()
        result.nodes.linkNodes(mark, after, null)
        states.set(state, { before, after, mark })
        if (marked.nodes.finals.has(state)) {
            result.nodes.linkNodes(after, result.nodes.final, null)
        }
    }
    result.nodes.linkNodes(
        result.nodes.initial,
        states.get(marked.nodes.initial)!.before,
        null,
    )
    for (const [state, from] of states) {
        for (const [target, chars] of state.out) {
            const to = states.get(target)!
            if (chars.has(marker)) {
                result.nodes.linkNodes(from.before, to.mark, null)
                result.nodes.linkNodes(from.after, to.mark, null)
            }
            const actualChars = CharSet.empty(maxCharacter).union(
                chars.without([{ min: marker, max: marker }]).ranges,
            )
            if (!actualChars.isEmpty) {
                result.nodes.linkNodes(from.before, to.before, actualChars)
                result.nodes.linkNodes(from.after, to.after, actualChars)
            }
        }
    }
    return NFA.fromFA(result)
}

/**
 * Returns whether the node or the elements of the node are effectively
 * quantified with a star.
 */
function isStared(node: Node): boolean {
    let max = getEffectiveMaximumRepetition(node)
    if (node.type === "Quantifier") {
        max *= node.max
    }
    return max > 10
}

/**
 * Check has after pattern
 */
function hasNothingAfterNode(node: ParentNode): boolean {
    const md = getMatchingDirection(node)

    for (
        let p:
            | Group
            | Pattern
            | CapturingGroup
            | LookaroundAssertion
            | Quantifier
            | Alternative = node;
        ;
        p = p.parent
    ) {
        if (p.type === "Assertion" || p.type === "Pattern") {
            return true
        }

        if (p.type !== "Alternative") {
            const parent: Quantifier | Alternative = p.parent
            if (parent.type === "Quantifier") {
                if (parent.max > 1) {
                    return false
                }
            } else {
                const lastIndex: number =
                    md === "ltr" ? parent.elements.length - 1 : 0
                if (parent.elements[lastIndex] !== p) {
                    return false
                }
            }
        }
    }
}

/**
 * Returns whether the given RE AST contains assertions.
 */
function containsAssertions(expression: NoParent<Expression>): boolean {
    try {
        visitAst(expression, {
            onAssertionEnter() {
                throw new Error()
            },
        })
        return false
    } catch (error) {
        return true
    }
}

/**
 * Returns whether the given RE AST contains assertions or unknowns.
 */
function containsAssertionsOrUnknowns(
    expression: NoParent<Expression>,
): boolean {
    try {
        visitAst(expression, {
            onAssertionEnter() {
                throw new Error()
            },
            onUnknownEnter() {
                throw new Error()
            },
        })
        return false
    } catch (error) {
        return true
    }
}

const creationOption: Transformers.CreationOptions = {
    ignoreAmbiguity: true,
    ignoreOrder: true,
}
const assertionTransformer = combineTransformers([
    Transformers.applyAssertions(creationOption),
    Transformers.removeUnnecessaryAssertions(creationOption),
    Transformers.inline(creationOption),
    Transformers.removeDeadBranches(creationOption),
])

/**

 * Create an NFA from the given element.
 *
 * The `partial` value determines whether the NFA perfectly represents the given
 * element. Some elements might contain features that cannot be represented
 * using NFA in which case a partial NFA will be created (e.g. the NFA of
 * `a|\bfoo\b` is equivalent to the NFA of `a`).
 */
function toNFA(
    parser: JS.Parser,
    element: JS.ParsableElement,
): { nfa: NFA; partial: boolean } {
    try {
        const { expression, maxCharacter } = parser.parseElement(element, {
            backreferences: "unknown",
            assertions: "parse",
        })

        let e
        if (containsAssertions(expression)) {
            e = transform(assertionTransformer, expression)
        } else {
            e = expression
        }

        return {
            nfa: NFA.fromRegex(
                e,
                { maxCharacter },
                { assertions: "disable", unknowns: "disable" },
            ),
            partial: containsAssertionsOrUnknowns(e),
        }
    } catch (error) {
        return {
            nfa: NFA.empty({
                maxCharacter: parser.ast.flags.unicode ? 0x10ffff : 0xffff,
            }),
            partial: true,
        }
    }
}

/**
 * Unions all given NFAs
 */
function unionAll(nfas: readonly ReadonlyNFA[]): ReadonlyNFA {
    if (nfas.length === 0) {
        throw new Error("Cannot union 0 NFAs.")
    } else if (nfas.length === 1) {
        return nfas[0]
    }

    const total = nfas[0].copy()
    for (let i = 1; i < nfas.length; i++) {
        total.union(nfas[i])
    }
    return total
}

const DFA_OPTIONS: DFA.CreationOptions = { maxNodes: 100_000 }

/**
 * Returns whether one NFA is a subset of another.
 */
function isSubsetOf(
    superset: ReadonlyNFA,
    subset: ReadonlyNFA,
): boolean | null {
    try {
        const a = DFA.fromIntersection(superset, subset, DFA_OPTIONS)
        const b = DFA.fromFA(subset, DFA_OPTIONS)
        a.minimize()
        b.minimize()
        return a.structurallyEqual(b)
    } catch (error) {
        return null
    }
}

const enum SubsetRelation {
    none,
    leftEqualRight,
    leftSubsetOfRight,
    leftSupersetOfRight,
    unknown,
}

/**
 * Returns the subset relation
 */
function getSubsetRelation(
    left: ReadonlyNFA,
    right: ReadonlyNFA,
): SubsetRelation {
    try {
        const inter = DFA.fromIntersection(left, right, DFA_OPTIONS)
        inter.minimize()

        const l = DFA.fromFA(left, DFA_OPTIONS)
        l.minimize()

        const r = DFA.fromFA(right, DFA_OPTIONS)
        r.minimize()

        const subset = l.structurallyEqual(inter)
        const superset = r.structurallyEqual(inter)

        if (subset && superset) {
            return SubsetRelation.leftEqualRight
        } else if (subset) {
            return SubsetRelation.leftSubsetOfRight
        } else if (superset) {
            return SubsetRelation.leftSupersetOfRight
        }
        return SubsetRelation.none
    } catch (error) {
        return SubsetRelation.unknown
    }
}

/**
 * The `getSubsetRelation` function assumes that both NFAs perfectly represent
 * their language.
 *
 * This function adjusts their subset relation to account for partial NFAs.
 */
function getPartialSubsetRelation(
    left: ReadonlyNFA,
    leftIsPartial: boolean,
    right: ReadonlyNFA,
    rightIsPartial: boolean,
): SubsetRelation {
    const relation = getSubsetRelation(left, right)

    if (!leftIsPartial && !rightIsPartial) {
        return relation
    }

    if (
        relation === SubsetRelation.none ||
        relation === SubsetRelation.unknown
    ) {
        return relation
    }

    if (leftIsPartial && !rightIsPartial) {
        switch (relation) {
            case SubsetRelation.leftEqualRight:
                return SubsetRelation.leftSupersetOfRight
            case SubsetRelation.leftSubsetOfRight:
                return SubsetRelation.none
            case SubsetRelation.leftSupersetOfRight:
                return SubsetRelation.leftSupersetOfRight

            default:
                throw new Error(relation)
        }
    }
    if (rightIsPartial && !leftIsPartial) {
        switch (relation) {
            case SubsetRelation.leftEqualRight:
                return SubsetRelation.leftSubsetOfRight
            case SubsetRelation.leftSubsetOfRight:
                return SubsetRelation.leftSubsetOfRight
            case SubsetRelation.leftSupersetOfRight:
                return SubsetRelation.none

            default:
                throw new Error(relation)
        }
    }

    // both are partial

    return SubsetRelation.none
}

/**
 * Returns the regex source of the given FA.
 */
function faToSource(fa: FiniteAutomaton, flags: ReadonlyFlags): string {
    try {
        return JS.toLiteral(fa.toRegex(), { flags }).source
    } catch (error) {
        return "<ERROR>"
    }
}

interface ResultBase {
    alternative: Alternative
    others: Alternative[]
}
interface DuplicateResult extends ResultBase {
    type: "Duplicate"
    others: [Alternative]
}
interface SubsetResult extends ResultBase {
    type: "Subset"
}
interface PrefixSubsetResult extends ResultBase {
    type: "PrefixSubset"
}
interface NestedSubsetResult extends ResultBase {
    type: "NestedSubset" | "NestedPrefixSubset"
    nested: NestedElement
}
interface SupersetResult extends ResultBase {
    type: "Superset"
}
interface OverlapResult extends ResultBase {
    type: "Overlap"
    overlap: NFA
}
type Result =
    | DuplicateResult
    | SubsetResult
    | PrefixSubsetResult
    | NestedSubsetResult
    | SupersetResult
    | OverlapResult

interface Options {
    parser: JS.Parser
    hasNothingAfter: boolean
    fastAst: boolean
    noNfa: boolean
    ignoreOverlap: boolean
}

/**
 * Tries to find duplication in the given alternatives
 */
function* findDuplicationAstFast(
    alternatives: Alternative[],
    flags: ReadonlyFlags,
): Iterable<Result> {
    // eslint-disable-next-line func-style -- x
    const shortCircuit: Parameters<typeof isEqualNodes>[3] = (a) => {
        return a.type === "CapturingGroup" ? false : null
    }

    for (let i = 0; i < alternatives.length; i++) {
        const alternative = alternatives[i]

        for (let j = 0; j < i; j++) {
            const other = alternatives[j]

            if (isEqualNodes(other, alternative, flags, shortCircuit)) {
                yield { type: "Duplicate", alternative, others: [other] }
            }
        }
    }
}

/**
 * Tries to find duplication in the given alternatives
 */
function* findDuplicationAst(
    alternatives: Alternative[],
    flags: ReadonlyFlags,
    hasNothingAfter: boolean,
): Iterable<Result> {
    // The AST comparison only supports omitting a suffix. In lookbehind,
    // leave prefix coverage to the direction-aware NFA comparison.
    const canOmitRight =
        hasNothingAfter &&
        alternatives.every((a) => getMatchingDirection(a) === "ltr")
    const isCoveredOptions: Parameters<typeof isCoveredNode>[2] = {
        flags,
        canOmitRight,
    }
    const isCoveredOptionsNoPrefix: Parameters<typeof isCoveredNode>[2] = {
        flags,
        canOmitRight: false,
    }

    for (let i = 0; i < alternatives.length; i++) {
        const alternative = alternatives[i]

        for (let j = 0; j < i; j++) {
            const other = alternatives[j]

            if (isCoveredNode(other, alternative, isCoveredOptions)) {
                if (isEqualNodes(other, alternative, flags)) {
                    yield {
                        type: "Duplicate",
                        alternative,
                        others: [other],
                    }
                } else if (
                    canOmitRight &&
                    !isCoveredNode(other, alternative, isCoveredOptionsNoPrefix)
                ) {
                    yield {
                        type: "PrefixSubset",
                        alternative,
                        others: [other],
                    }
                } else {
                    yield { type: "Subset", alternative, others: [other] }
                }
            }
        }
    }
}

/** Finds nested paths covered by earlier alternatives. */
function* findNestedDuplication(
    alternative: Alternative,
    previous: [NFA, boolean, Alternative][],
    parser: JS.Parser,
    prefix: boolean,
): Iterable<NestedSubsetResult> {
    if (previous.length === 0) {
        return
    }

    const covered: NestedElement[] = []
    for (const nested of getNestedElements(alternative)) {
        if (
            covered.some((n) => n.start <= nested.start && nested.end <= n.end)
        ) {
            continue
        }

        let nfa: NFA
        try {
            nfa = toNestedNFA(parser, alternative, nested)
        } catch (error) {
            continue
        }
        if (nfa.isEmpty) {
            continue
        }

        const overlapping = previous.filter(
            ([other]) => !nfa.isDisjointWith(other),
        )
        if (
            overlapping.length > 0 &&
            isSubsetOf(unionAll(overlapping.map(([other]) => other)), nfa)
        ) {
            covered.push(nested)
            yield {
                type: prefix ? "NestedPrefixSubset" : "NestedSubset",
                alternative,
                nested,
                others: overlapping.map(([, , other]) => other),
            }
        }
    }
}

/**
 * Tries to find duplication in the given alternatives.
 *
 * It will search for prefix duplications. I.e. the alternative `ab` in `a|ab`
 * is a duplicate of `a` because if `ab` accepts, `a` will have already accepted
 * the input string. This makes `ab` effectively useless.
 *
 * This operation will modify the given NFAs.
 */
function* findPrefixDuplicationNfa(
    alternatives: [NFA, boolean, Alternative][],
    parser: JS.Parser,
    skipNested: ReadonlySet<Alternative>,
): Iterable<Result> {
    if (alternatives.length === 0) {
        return
    }

    // For two alternatives `A|B`, `B` is useless if `B` is a subset of `A[^]*`

    const all = NFA.all({ maxCharacter: alternatives[0][0].maxCharacter })

    for (let i = 0; i < alternatives.length; i++) {
        const [nfa, partial, alternative] = alternatives[i]

        if (!partial) {
            const overlapping = alternatives
                .slice(0, i)
                .filter(([otherNfa]) => !nfa.isDisjointWith(otherNfa))

            if (overlapping.length >= 1) {
                const othersNfa = unionAll(overlapping.map(([n]) => n))
                const others = overlapping.map(([, , a]) => a)

                // Only checking for a subset relation is sufficient here.
                // Duplicates are VERY unlikely. (Who would use alternatives
                // like `a|a[^]*`?)

                if (isSubsetOf(othersNfa, nfa)) {
                    yield { type: "PrefixSubset", alternative, others }
                }
            }
        }

        if (!skipNested.has(alternative)) {
            yield* findNestedDuplication(
                alternative,
                alternatives.slice(0, i),
                parser,
                true,
            )
        }

        if (getMatchingDirection(alternative) === "ltr") {
            nfa.append(all)
        } else {
            nfa.prepend(all)
        }
    }
}

/**
 * Tries to find duplication in the given alternatives.
 */
function* findDuplicationNfa(
    alternatives: Alternative[],
    flags: ReadonlyFlags,

    { hasNothingAfter, parser, ignoreOverlap }: Options,
): Iterable<Result> {
    const previous: [NFA, boolean, Alternative][] = []
    const skipNested = new Set<Alternative>()
    for (let i = 0; i < alternatives.length; i++) {
        const alternative = alternatives[i]
        const { nfa, partial } = toNFA(parser, alternative)

        const overlapping = previous.filter(
            ([otherNfa]) => !nfa.isDisjointWith(otherNfa),
        )

        if (overlapping.length >= 1) {
            const othersNfa = unionAll(overlapping.map(([n]) => n))
            const othersPartial = overlapping.some(([, p]) => p)
            const others = overlapping.map(([, , a]) => a)

            const relation = getPartialSubsetRelation(
                nfa,
                partial,
                othersNfa,
                othersPartial,
            )

            switch (relation) {
                case SubsetRelation.leftEqualRight:
                    skipNested.add(alternative)
                    if (others.length === 1) {
                        // only return "duplicate" if there is only one other
                        // alternative
                        yield {
                            type: "Duplicate",
                            alternative,
                            others: [others[0]],
                        }
                    } else {
                        yield { type: "Subset", alternative, others }
                    }
                    break

                case SubsetRelation.leftSubsetOfRight:
                    skipNested.add(alternative)
                    yield { type: "Subset", alternative, others }
                    break

                case SubsetRelation.leftSupersetOfRight: {
                    const reorder = canReorder([alternative, ...others], flags)

                    if (reorder) {
                        // This alternative covers earlier removable ones. It
                        // must not in turn use them to justify removing its
                        // own nested elements.
                        skipNested.add(alternative)
                        // We are allowed to freely reorder the alternatives.
                        // This means that we can reverse the order of our
                        // alternatives to convert the superset into a subset.
                        for (const other of others) {
                            yield {
                                type: "Subset",
                                alternative: other,
                                others: [alternative],
                            }
                        }
                    } else {
                        yield { type: "Superset", alternative, others }
                    }
                    break
                }

                case SubsetRelation.none:
                case SubsetRelation.unknown:
                    if (!ignoreOverlap) {
                        yield {
                            type: "Overlap",
                            alternative,
                            others,
                            overlap: NFA.fromIntersection(nfa, othersNfa),
                        }
                    }
                    break

                default:
                    throw new Error(relation)
            }
        }

        if (!skipNested.has(alternative)) {
            yield* findNestedDuplication(alternative, previous, parser, false)
        }
        previous.push([nfa, partial, alternative])
    }

    if (hasNothingAfter) {
        yield* findPrefixDuplicationNfa(previous, parser, skipNested)
    }
}

/**
 * Tries to find duplication in the given alternatives
 */
function* findDuplication(
    alternatives: Alternative[],
    flags: ReadonlyFlags,
    options: Options,
): Iterable<Result> {
    // AST-based approach
    if (options.fastAst) {
        yield* findDuplicationAstFast(alternatives, flags)
    } else {
        yield* findDuplicationAst(alternatives, flags, options.hasNothingAfter)
    }

    // NFA-based approach
    if (!options.noNfa) {
        yield* findDuplicationNfa(alternatives, flags, options)
    }
}

const RESULT_TYPE_ORDER: Result["type"][] = [
    "Duplicate",
    "Subset",
    "PrefixSubset",
    "NestedSubset",
    "NestedPrefixSubset",
    "Superset",
    "Overlap",
]

/**
 * Returns an array of the given results that is sorted by result type from
 * most important to least important.
 */
function deduplicateResults(
    unsorted: Iterable<Result>,
    { reportExp }: FilterInfo,
): Result[] {
    const results = [...unsorted].sort(
        (a, b) =>
            RESULT_TYPE_ORDER.indexOf(a.type) -
            RESULT_TYPE_ORDER.indexOf(b.type),
    )

    const seen = new Map<Alternative, Result["type"]>()
    const nestedSeen = new Map<Alternative, NestedElement[]>()
    return results.filter((result) => {
        const { alternative, type } = result
        const firstSeen = seen.get(alternative)

        if (
            (type === "NestedSubset" || type === "NestedPrefixSubset") &&
            (firstSeen === undefined ||
                firstSeen === "NestedSubset" ||
                firstSeen === "NestedPrefixSubset")
        ) {
            const elements = nestedSeen.get(alternative) || []
            if (
                elements.some(
                    (n) =>
                        n.start <= result.nested.start &&
                        result.nested.end <= n.end,
                )
            ) {
                return false
            }
            elements.push(result.nested)
            nestedSeen.set(alternative, elements)
            seen.set(alternative, firstSeen || type)
            return true
        }

        if (firstSeen === undefined) {
            seen.set(alternative, type)
            return true
        }

        if (
            reportExp &&
            (firstSeen === "PrefixSubset" ||
                firstSeen === "NestedPrefixSubset") &&
            (type === "Superset" || type === "Overlap")
        ) {
            // Prefix subset might overshadow some other results (Superset or
            // Overlap) that report exponential backtracking. In this case, we
            // want to report BOTH the Prefix subset and one Superset or
            // Overlap.
            seen.set(alternative, type)
            return true
        }

        return false
    })
}

