 quoting/character descriptions:\",\"- Strict subset: `Unexpected useless element. All paths of <alternative> that go through <element> are a strict subset of <covered alternatives>. This element can be removed.`\",\"- Prefix coverage: `Unexpected useless element. All paths of <alternative> that go through <element> are already covered by <covered alternatives>. This element can be removed.`\",\"- When that element contains capturing groups, append the existing warning: ` Careful! This alternative contains capturing groups which might be difficult to remove.`\",\"\",\"Public rule behavior, message text and locations are part of the contract; internal algorithms and helper names are not prescribed.\",\"\",\"Environment: Node and npm dependencies are preinstalled. Run the focused rule suite with `node node_modules/mocha/bin/mocha --require ts-node/register tests/lib/rules/no-dupe-disjunctions.ts --reporter spec --no-color --timeout 60000`.\",\"\",\"\",\"Inspect your final diff and run relevant existing checks. Report what changed and what was verified.\",\"\"]}],\"before_structure\":[],\"batch_change\":[{\"path\":\"tool/exec-79b87966-912f-4bfb-9eda-3b34fbdffda3/input\",\"start\":1,\"lines\":[\"*** Begin Patch\",\"*** Update File: <SOURCE_ROOT>/round-10-calibration/cases/regexp-404/lib/rules/no-dupe-disjunctions.ts\",\"@@\",\"-        const parent = current.parent!\",\"+        const parent: Node = current.parent!\",\"         switch (parent.type) {\",\"-            case \\\"Alternative\\\":\",\"-                selected = concat(\",\"-                    parent.elements.map((e) =>\",\"-                        e === current ? selected : parse(e),\",\"-                    ),\",\"-                )\",\"+            case \\\"Alternative\\\": {\",\"+                const elements: NoParent<REElement>[] = []\",\"+                for (const e of parent.elements) {\",\"+                    elements.push(e === current ? selected : parse(e))\",\"+                }\",\"+        